//! TWIST — the planar twister (`TWIST/T.EXE`).
//!
//! The shipped effect is `MAIN.C` (Microsoft C, 16-bit `int`s) linked with
//! `TWIST.ASM`, `ASM.ASM` and the generated `TWSTLOOP.INC`
//! (`TWIST/MAKEFILE:1-16`). A static 320×200 texture is melted: each displayed
//! scanline is one of the 200 texture rows, chosen by a sine of a phase that
//! advances faster every frame. The two 16,000-plane-byte halves of VGA memory
//! are the source's double buffer, flipped through CRTC start address 0x0C.
//!
//! The port transliterates the source: `r` is a wrapping 16-bit accumulator,
//! `sin1024[...]*25/64` truncates toward zero, `w % 200` maps the sine peak
//! 200 to row 0, and the shipped `TWSTLOOP.INC`'s 16,000 bytes are consumed as
//! shipped (including the generator's `v[0] = 63` quirk). Each texture byte is
//! four identical pixels, the map-mask-15 write. The palette is the C's
//! 8-bit write masked to the DAC's six bits, not `Palette::from_vga`'s `>> 2`.
//!
//! `docs/fidelity/twist.md` is the full note: the capture, the substitutions
//! and the comparison.

use sr_engine::part::{Part, PartCtx, PartError, PartStatus};
use sr_engine::Palette;

use crate::parts::glenz::tables::SIN1024;

/// The registry name (`parts::registry`).
pub const TWIST_NAME: &str = "twist";

/// `while(!kbhit() && frame<4444)` (`MAIN.C:49`): frames 0..4,443 draw, and
/// the 4,445th call returns `Finished` without drawing.
pub const LAST_FRAME: u32 = 4_444;

/// The displayed picture's width: 200 logical rows of 80 plane bytes, each
/// byte four pixels (`inittwk` leaves CRTC 0x09 at mode 13h's 0x41, so the
/// frame is 320×200 double-scanned; the port models the 200 raw rows).
const SCREEN_WIDTH: usize = 320;
const SCREEN_HEIGHT: usize = 200;
const PLANE_BYTES_PER_ROW: usize = 80;

/// `vram1 = (char far *)0xa0000000L` (`MAIN.C:13`): the first buffer, pixel
/// origin 0 in the port's chunky convention (one plane byte is four pixels).
const PAGE_1: u32 = 0;

/// `vram2 = (char far *)0xa8000000L` (`MAIN.C:14`): plane-byte offset 0x8000
/// inside the same 64 KB window, i.e. pixel 0x8000 × 4 = 131,072. A 640×400
/// surface holds both pages; page 2's last row ends at 195,071.
const PAGE_2: u32 = 4 * 0x8000;

/// The selected texture row for each of the 200 displayed scanlines, for part
/// frame `frame` (0-based).
///
/// `doit` (`MAIN.C:44-78`) resets a 16-bit `r` every frame, increments `ra`
/// first (`ra = frame + 1`) and advances `r` by `ra` after each row. The
/// compiler keeps `r` in `bx` (`MAIN.OBJ` text 0xf0-0x113), so the product is
/// taken modulo 65,536; the sine index is `((r >> 6) & 511) + 256`, which masks
/// bit 15 out and never reaches the −256 at index 768.
///
/// `w = sin1024[index] * 25 / 64 + 100` is the Microsoft C sign-restore
/// division: it truncates toward zero, so `sin = -255` gives `w = 1`, not the
/// floor's 0. `w` is then in 1..=200, and `twister`'s clamp is modulo 200
/// (`TWIST.ASM:26-35`): the sine peak `w = 200` selects generated row **0**,
/// not row 199. Row 0 is the peak every frame, so `rows(frame)[0] == 0`.
pub fn rows(frame: u32) -> [u8; 200] {
    // `ra++` on the source's 16-bit `int`; part frames stop at 4,443, so this
    // is 1..4,444 in every frame the part draws.
    let ra = frame.wrapping_add(1) as u16;
    let mut selected = [0u8; SCREEN_HEIGHT];
    for (y, selected_row) in selected.iter_mut().enumerate() {
        // `r += ra` in `bx`: the 16-bit product wraps (from frame 329 the last
        // selected row sees a wrapped value; frame 327's final, unused add is
        // the first to wrap at all).
        let r = (y as u16).wrapping_mul(ra);
        let index = (((r >> 6) & 511) as usize) + 256;
        // Signed division truncating toward zero, as `idiv` emits it.
        let w = (i32::from(SIN1024[index]) * 25) / 64 + 100;
        *selected_row = (w % 200) as u8;
    }
    selected
}

