/// The source's 256-entry palette (`MAIN.C:91-99`), six bits per channel.
///
/// The C writes 8-bit bytes `a/3`, `2a/3` and `a` to the DAC, and the DAC
/// masks each write to its low six bits (DOSBox's `write_p3c9` does
/// `val &= 0x3f`). Entry `a` is therefore `((a/3)&63, (2a/3)&63, a&63)`;
/// entry 63 is `(21,42,63)`, entry 191 is white and entry 192 is black. This
/// is **not** `Palette::from_vga`'s `>> 2`, which is for an 8-bit CMAP/module
/// palette and would darken every colour fourfold.
fn twist_palette() -> Palette {
    // `inittwk` first writes 768 zero bytes: every DAC entry black.
    let mut palette = Palette::new();
    for a in 0..256u16 {
        palette.set_entry(a as u8, [(a / 3) as u8, ((2 * a) / 3) as u8, a as u8]);
    }
    palette
}

/// Draw one page: for each destination row `y`, copy the selected texture row
/// (80 plane bytes) to `page + y*320`, each byte written four times.
///
/// `twister` (`TWIST.ASM:16-46`) calls the generated left and right routines
/// for the row `w % 200`; the generated code's `mov ax,...` word stores write
/// 80 plane bytes, and the map mask `0x0F` replicates each byte into four
/// adjacent pixels.
fn draw_page(pixels: &mut [u8], page: u32, frame: u32) {
    let selected = rows(frame);
    for (y, &source_row) in selected.iter().enumerate() {
        let source = &TEXTURE[source_row as usize];
        let start = page as usize + y * SCREEN_WIDTH;
        let destination = &mut pixels[start..start + SCREEN_WIDTH];
        for (x, &byte) in source.iter().enumerate() {
            destination[x * 4..x * 4 + 4].fill(byte);
        }
    }
}

/// The TWIST part.
#[derive(Default)]
pub struct Twist;

impl Twist {
    pub fn new() -> Twist {
        Twist
    }
}

impl Part for Twist {
    fn name(&self) -> &'static str {
        TWIST_NAME
    }

    fn init(&mut self, ctx: &mut PartCtx) -> Result<(), PartError> {
        // `inittwk` (`ASM.ASM:34-63`) leaves mode 13h's CRTC 0x09 = 0x41 (its
        // "400 rows" write is commented out), so the emulator reports a
        // 320×200, double-scanned frame. The port models the 200 raw rows, as
        // the rest of the port does for double-scanned parts, and the plane
        // rows are 80 bytes = 320 chunky pixels, mode 13h's untouched 0x13.
        ctx.view.width = SCREEN_WIDTH as u16;
        ctx.view.height = SCREEN_HEIGHT as u16;
        ctx.view.double_scan = false;
        ctx.view.y_line_offset = Some(SCREEN_WIDTH as u16);
        ctx.view.set_origin(PAGE_1);
        ctx.view.pan = 0;
        ctx.view.split = None;
        // The overscan starts black; `waitb`'s Scroll-Lock toggle is dropped
        // (the reference is captured with no key, so the branch never runs).
        ctx.view.border = Some(0);
        // `inittwk` clears all four planes through map mask 0x0F; in the port's
        // chunky mapping that is the whole 640×400 surface. (`memset(vram,0,
        // 64000)` and `vram[a]=a` are dead: the first twister draw overwrites
        // the visible page.)
        ctx.surface.pixels_mut().fill(0);
        // `setpalarea(palette,0,256)` (`MAIN.C:99`) uploads all 768 bytes
        // before `doit`; the palette never changes again.
        ctx.set_palette(twist_palette());
        Ok(())
    }

    fn frame(&mut self, ctx: &mut PartCtx) -> PartStatus {
        // `while(!kbhit() && frame<4444)` checks both conditions at the top:
        // the exit tick and the 4,445th call draw nothing.
        if ctx.exit_requested || ctx.frame >= LAST_FRAME {
            return PartStatus::Finished;
        }
        // `flip` starts 0 and is incremented before its switch: part frame 0
        // takes case 1 (draw buffer 1, display start 0x00), frame 1 case 0
        // (draw buffer 2, display start 0x80). Even frames draw page 1 at
        // origin 0, odd frames page 2 at 131,072; the page just drawn is the
        // one the beam shows.
        let page = if ctx.frame % 2 == 0 { PAGE_1 } else { PAGE_2 };
        draw_page(ctx.surface.pixels_mut(), page, ctx.frame);
        ctx.view.set_origin(page);
        PartStatus::Continuing
    }
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use sr_engine::{Engine, IndexedFrame, View};

    use super::*;

    /// The shipped include, read from the vendored tree. Unit tests run from
    /// the crate's own directory, so the repository root is `../..`.
    const INCLUDE: &str = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../upstream/SecondReality/TWIST/TWSTLOOP.INC"
    );

    /// The rows the source formula selects at eight frames, recorded as 200
    /// bytes each from `sin1024[((r>>6)&511)+256]*25/64+100` with a 16-bit
    /// wrapping `r`. The frames straddle the opening two-band phase, the first
    /// in-iteration wrap (327), a mid-run frame and the last drawn frame.
    const EXPECTED_ROWS: [(u32, &str); 8] = [
        (0, ""),
        (1, ""),
        (2, ""),
        (3, ""),
        (99, ""),
        (327, ""),
        (999, ""),
        (4443, ""),
    ];

    fn decode(hex: &str) -> [u8; 200] {
        assert_eq!(hex.len(), 400, "200 bytes as hex");
        let mut out = [0u8; 200];
        for (index, byte) in out.iter_mut().enumerate() {
            *byte = u8::from_str_radix(&hex[index * 2..index * 2 + 2], 16).expect("hex digits");
        }
        out
    }

    fn transitions(selected: &[u8; 200]) -> usize {
        selected
            .windows(2)
            .filter(|pair| pair[0] != pair[1])
            .count()
    }

    fn distinct(selected: &[u8; 200]) -> usize {
        selected.iter().collect::<BTreeSet<_>>().len()
    }

    fn expanded(source_row: usize) -> Vec<u8> {
        let mut row = Vec::with_capacity(SCREEN_WIDTH);
        for &byte in &TEXTURE[source_row] {
            row.extend_from_slice(&[byte; 4]);
        }
        row
    }

    fn start() -> (Engine, Twist, IndexedFrame) {
        let mut engine = Engine::new(640, 400, View::new(320, 200));
        let mut part = Twist::new();
        engine.start(&mut part).expect("TWIST starts");
        let frame = IndexedFrame::new(320, 200);
        (engine, part, frame)
    }

    #[test]
    fn the_selected_rows_are_the_sources_16_bit_phase() {
        for (frame, hex) in EXPECTED_ROWS {
            assert_eq!(rows(frame), decode(hex), "frame {frame}");
        }

        // Row 0 is the sine peak every frame: sin1024[256] = 256, so w = 200
        // and the twister's modulo-200 clamp selects generated row 0.
        for (frame, _) in EXPECTED_ROWS {
            assert_eq!(rows(frame)[0], 0, "frame {frame}");
        }

        // The measured two-band opening: frame 0 is generated row 0 in rows
        // 0..63 and generated row 199 in rows 64..199; frame f's boundary is
        // ceil(64/(f+1)) through the first four frames.
        let zero = rows(0);
        assert!(zero[..64].iter().all(|&row| row == 0));
        assert!(zero[64..].iter().all(|&row| row == 199));
        assert_eq!(zero.iter().position(|&row| row != 0), Some(64));
        for frame in 0..4u32 {
            let ra = frame as usize + 1;
            let boundary = 64usize.div_ceil(ra);
            let selected = rows(frame);
            assert!(
                selected[..boundary].iter().all(|&row| row == 0),
                "frame {frame}"
            );
            assert!(
                selected[boundary..].iter().all(|&row| row == 199),
                "frame {frame}"
            );
            assert_eq!(
                selected.iter().position(|&row| row != 0),
                Some(boundary),
                "frame {frame}"
            );
        }

        // The rows the source formula selects at the later recorded frames,
        // as transition and distinct-row counts (the full bytes are above).
        assert_eq!(transitions(&rows(99)), 124);
        assert_eq!(distinct(&rows(99)), 125);
        assert_eq!(transitions(&rows(999)), 196);
        assert_eq!(distinct(&rows(999)), 136);
        assert_eq!(transitions(&rows(4443)), 199);
        assert_eq!(distinct(&rows(4443)), 102);

        // The 16-bit `r`: a full iteration's 200 adds at frame 326 are
        // 200·327 = 65,400, inside a word; frame 327's final (unused) add is
        // 200·328 = 65,600 and wraps. No *selected* row has wrapped yet: the
        // first is frame 329's y = 199 (199·330 = 65,670 → 134).
        let inside_before_327 = u32::from(200u16) * 327;
        let final_add_at_327 = u32::from(200u16) * 328;
        let last_selected_row_at_328 = u32::from(199u16) * 329;
        assert!(inside_before_327 < 65_536, "{inside_before_327}");
        assert!(final_add_at_327 > 65_536, "{final_add_at_327}");
        let wrapped_final_add = (final_add_at_327 & 0xffff) as u16;
        assert_eq!(wrapped_final_add, 64);
        assert!(
            last_selected_row_at_328 < 65_536,
            "{last_selected_row_at_328}"
        );
        let wrapped_last_row = ((u32::from(199u16) * 330) & 0xffff) as u16;
        assert_eq!(wrapped_last_row, 134);
        let mut previous = 0u16;
        for y in 0..200u16 {
            let r = y.wrapping_mul(328);
            assert!(r >= previous, "frame 327, row {y}");
            previous = r;
        }

        // The division truncates toward zero, not floor:
        // * frame 327, y = 199: sin1024[763] = -255, so -6375/64 = -99 and
        //   w = 1 (floor would be -100, w = 0);
        // * frame 82, y = 199: sin1024[514] = -3, so -75/64 = -1 and w = 99
        //   (floor would be -2, w = 98).
        let r = 199u16.wrapping_mul(328);
        let index = (((r >> 6) & 511) as usize) + 256;
        assert_eq!(SIN1024[index], -255);
        assert_eq!(rows(327)[199], 1);
        let r = 199u16.wrapping_mul(83);
        let index = (((r >> 6) & 511) as usize) + 256;
        assert_eq!(SIN1024[index], -3);
        assert_eq!(rows(82)[199], 99);

        // The sine peak inside a wrapped-accumulator frame still selects row 0.
        let r = 100u16.wrapping_mul(328);
        let index = (((r >> 6) & 511) as usize) + 256;
        assert_eq!(SIN1024[index], 256);
        assert_eq!(rows(327)[100], 0);

        // The cap: the last drawn frame is 4,443, and the frame the 4,445th
        // call must *not* draw is a different picture.
        assert_eq!(LAST_FRAME, 4_444);
        assert_ne!(rows(LAST_FRAME - 1), rows(LAST_FRAME));
    }

    /// Stats gathered while walking the generated include.
    #[derive(Default)]
    struct IncludeStats {
        left_labels: usize,
        right_labels: usize,
        stores: usize,
        immediates: usize,
        /// For each row, which of the 80 plane bytes a store wrote.
        written: Vec<[bool; PLANE_BYTES_PER_ROW]>,
    }

    /// Reconstruct `TEXTURE` from the shipped `TWSTLOOP.INC`, walking its
    /// `twist<N>l`/`twist<N>r` labels and its `mov ax,0XXXXh` /
    /// `mov ds:[di+N],ax` stores. The generator's run-length immediates are
    /// carried between stores exactly as the assembler would.
    fn texture_from_include(include: &str) -> ([[u8; PLANE_BYTES_PER_ROW]; 200], IncludeStats) {
        let mut texture = [[0u8; PLANE_BYTES_PER_ROW]; 200];
        let mut stats = IncludeStats {
            written: vec![[false; PLANE_BYTES_PER_ROW]; 200],
            ..IncludeStats::default()
        };
        let mut current: Option<(usize, bool)> = None; // (row, right half)
        let mut ax: Option<u16> = None;
        for line in include.lines() {
            let line = line.trim();
            if let Some(label) = line.strip_suffix(':') {
                if let Some(name) = label.strip_prefix("twist") {
                    let (right, number) = match (name.strip_suffix('l'), name.strip_suffix('r')) {
                        (Some(number), _) => (false, number),
                        (_, Some(number)) => (true, number),
                        _ => continue,
                    };
                    if let Ok(row) = number.parse::<usize>() {
                        current = Some((row, right));
                        ax = None;
                        if right {
                            stats.right_labels += 1;
                        } else {
                            stats.left_labels += 1;
                        }
                        continue;
                    }
                }
            }
            // The generated pixel immediates are four hex digits; the
            // routines' map-mask setup is the three-digit `0f02h` and is not
            // one of them.
            if let Some(rest) = line.strip_prefix("mov ax,0") {
                if let Some(hex) = rest.strip_suffix('h') {
                    if hex.len() == 4 {
                        ax = Some(u16::from_str_radix(hex, 16).expect("a hex immediate"));
                        stats.immediates += 1;
                        continue;
                    }
                }
            }
            if let Some(rest) = line.strip_prefix("mov ds:[di+") {
                if let Some(offset) = rest.strip_suffix("],ax") {
                    let offset: usize = offset.parse().expect("a store offset");
                    let value = ax.expect("a store before any immediate");
                    let (row, right) = current.expect("a store outside a routine");
                    let base = if right { 40 } else { 0 };
                    assert_eq!(right, offset >= 40, "the half and the offset disagree");
                    assert!(
                        (base..base + 40).contains(&offset),
                        "row {row}: offset {offset} is outside its half"
                    );
                    texture[row][offset] = value as u8;
                    texture[row][offset + 1] = (value >> 8) as u8;
                    stats.written[row][offset] = true;
                    stats.written[row][offset + 1] = true;
                    stats.stores += 1;
                }
            }
        }
        (texture, stats)
    }

    #[test]
    fn the_texture_table_is_the_shipped_twstloop() {
        let include = std::fs::read_to_string(INCLUDE).expect("the vendored TWSTLOOP.INC");
        let (reconstructed, stats) = texture_from_include(&include);

        // The include's shape, measured over the whole file: 200 left and 200
        // right routines, 20 word stores each (80 plane bytes a row), and the
        // generator's 1,549 run-length immediates.
        assert_eq!(stats.left_labels, 200);
        assert_eq!(stats.right_labels, 200);
        assert_eq!(stats.stores, 8_000);
        assert_eq!(stats.immediates, 1_549);
        for (row, written) in stats.written.iter().enumerate() {
            assert!(
                written.iter().all(|&byte| byte),
                "row {row} does not write all 80 plane bytes"
            );
        }

        // The port's constant is exactly those bytes — the shipped include,
        // including the generator's `v[0]=63` quirk.
        assert_eq!(reconstructed, TEXTURE);

        // Its byte values: 55 distinct, all in 0..=63 (the picture only ever
        // indexes the first 64 palette entries).
        let mut seen = [false; 64];
        for row in &TEXTURE {
            for &byte in row {
                assert!(byte < 64, "texture byte {byte} is outside the 6-bit DAC");
                seen[byte as usize] = true;
            }
        }
        assert_eq!(seen.iter().filter(|&&used| used).count(), 55);

        // The `v[0]=63` artifact: 121 of the 200 rows begin 0x3F — their first
        // four pixels are palette index 63. Row 0 is clean; row 6 is one of
        // the rows the generator stamped.
        assert_eq!(TEXTURE.iter().filter(|row| row[0] == 0x3f).count(), 121);
        assert_eq!(TEXTURE[0][0], 0);
        assert_eq!(TEXTURE[6][0], 0x3f);

        // 191 of the 200 rows are distinct.
        let distinct = TEXTURE.iter().collect::<BTreeSet<_>>().len();
        assert_eq!(distinct, 191);
    }

    #[test]
    fn the_pages_alternate_origins_zero_and_131072() {
        let (mut engine, mut part, mut frame) = start();
        assert_eq!(engine.view().y_line_offset, Some(320));
        assert_eq!((engine.view().width, engine.view().height), (320, 200));
        assert!(!engine.view().double_scan);
        assert!(engine.view().split.is_none());

        for part_frame in 0..4u32 {
            assert_eq!(
                engine.tick(&mut part, &mut frame),
                PartStatus::Continuing,
                "frame {part_frame}"
            );
            let page = if part_frame % 2 == 0 { 0 } else { 131_072 };
            assert_eq!(engine.view().start_addr, page, "frame {part_frame}");

            let selected = rows(part_frame);
            for &y in &[0u16, 63, 64, 100, 199] {
                assert_eq!(
                    frame.row(y),
                    &expanded(selected[y as usize] as usize)[..],
                    "frame {part_frame}, row {y}"
                );
            }
            // The map-mask-15 write: every texture byte is four identical
            // pixels, so each row is constant in groups of four.
            for y in 0..200u16 {
                let row = frame.row(y);
                for x in 0..PLANE_BYTES_PER_ROW {
                    let pixel = row[x * 4];
                    assert_eq!(
                        &row[x * 4..x * 4 + 4],
                        &[pixel; 4][..],
                        "frame {part_frame}, row {y}, group {x}"
                    );
                }
            }
        }

        // The two pages are inside the 640×400 surface and do not overlap.
        let page_one_end = PAGE_1 as usize + 199 * 320 + 319;
        let page_two_end = PAGE_2 as usize + 199 * 320 + 319;
        let surface_pixels = engine.surface().pixels().len();
        assert_eq!(page_one_end, 63_999);
        assert_eq!(page_two_end, 195_071);
        assert!(page_one_end < PAGE_2 as usize);
        assert!(page_two_end < surface_pixels);
    }

    #[test]
    fn the_palette_is_the_eight_bit_write_masked_to_six_bits() {
        let palette = twist_palette();
        for a in 0..256u16 {
            let expected = [
                ((a / 3) & 63) as u8,
                (((2 * a) / 3) & 63) as u8,
                (a & 63) as u8,
            ];
            assert_eq!(palette.entry(a as u8), expected, "entry {a}");
        }
        // The three entries the brief names, plus entry 31 (the border colour
        // the dropped Scroll-Lock branch would have shown).
        assert_eq!(palette.entry(63), [21, 42, 63]);
        assert_eq!(palette.entry(191), [63, 63, 63]);
        assert_eq!(palette.entry(192), [0, 0, 0]);
        assert_eq!(palette.entry(31), [10, 20, 31]);

        // The same bytes through `from_vga` are four times darker — the wrong
        // conversion for a DAC write.
        let mut vga = [0u8; 768];
        for (a, entry) in vga.chunks_exact_mut(3).enumerate() {
            entry[0] = ((a as u16) / 3) as u8;
            entry[1] = ((2 * a as u16) / 3) as u8;
            entry[2] = a as u8;
        }
        let shifted = Palette::from_vga(&vga);
        assert_ne!(shifted, palette);
        assert_eq!(shifted.entry(63), [5, 10, 15]);
        assert_eq!(palette.entry(63), [21, 42, 63]);
    }

    #[test]
    fn the_first_frames_are_the_measured_two_band_phase() {
        // The source formula's own bands.
        let zero = rows(0);
        assert!(zero[..64].iter().all(|&row| row == 0));
        assert!(zero[64..].iter().all(|&row| row == 199));

        // The composed picture. `K0` was measured on exactly this content:
        // frame 0 is the two-band fingerprint, and frame f's first row that
        // differs from row 0 is ceil(64/(f+1)) through the opening frames.
        let (mut engine, mut part, mut frame) = start();
        for part_frame in 0..4u32 {
            engine.tick(&mut part, &mut frame);
            let ra = part_frame as usize + 1;
            let boundary = 64usize.div_ceil(ra);
            let row_zero = expanded(0);
            let row_last = expanded(199);
            for y in 0..200u16 {
                let want = if (y as usize) < boundary {
                    &row_zero
                } else {
                    &row_last
                };
                assert_eq!(frame.row(y), &want[..], "frame {part_frame}, row {y}");
            }
        }
        assert_eq!(rows(0)[0], 0);
        assert_eq!(rows(0)[63], 0);
        assert_eq!(rows(0)[64], 199);
        assert_eq!(rows(0)[199], 199);
    }
}
